import{_ as l,c as e,o as i,ah as r}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"风火家人","description":"周易折中 - 风火家人","frontmatter":{"title":"风火家人","description":"周易折中 - 风火家人"},"headers":[],"relativePath":"zh/classics/zhezhong/043.md","filePath":"zh/classics/zhezhong/043.md"}'),h={name:"zh/classics/zhezhong/043.md"};function p(n,a,d,t,s,o){return i(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="风火家人" tabindex="-1">风火家人 <a class="header-anchor" href="#风火家人" aria-label="Permalink to “风火家人”">​</a></h1><h3 id="程传" tabindex="-1">程传 <a class="header-anchor" href="#程传" aria-label="Permalink to “程传”">​</a></h3><p>〈家人〉序卦：“夷者，伤也。伤于外者，必反于家，故受之以《家人》。夫伤困于外，则必反于内，《家人》所以次《明夷》也。《家人》，家内之道也。父子之亲，夫妇之义，尊卑长幼之序，正伦理，笃恩义，家人之道也。卦外巽内离，为风自火出，火炽则风生，风生自火，自内而出也。自内而出，由家而及于外之象。二与五正男女之位，于内外为《家人》之道。明于内而巽于外，处家之道也。夫人有诸身者，则能施于家；行于家者，则能施于国；至于天下治，治天下之道，盖治家之道也。推而行之于外耳，故取自内而出之象，为《家人》之义也。文中子书以明内齐外为义，古今善之，非取象之意也。所谓齐乎巽，言万物洁齐于巽方，非巽有齐义也，如战乎乾，乾非有战义也。”</p><p>家人：利女贞</p><h3 id="本义" tabindex="-1">本义 <a class="header-anchor" href="#本义" aria-label="Permalink to “本义”">​</a></h3><p>家人者，一家之人。卦之九五、六二外内各得其正，故为家人。利女贞者，欲先正乎内也，内正则外无不正矣。</p><h3 id="程传-1" tabindex="-1">程传 <a class="header-anchor" href="#程传-1" aria-label="Permalink to “程传”">​</a></h3><p>家人之道，利在女正。女正则家道正矣。夫夫妇妇而家道正，独云“利女贞”者，夫正者身正也，女正者家正也。女正则男正可知矣。</p><h3 id="集说" tabindex="-1">集说 <a class="header-anchor" href="#集说" aria-label="Permalink to “集说”">​</a></h3><ul><li>杨氏时曰 ：家人者，治家人之道也。齐家自夫妇始。舜观刑于二女，文王刑于寡妻，至于兄弟。利女贞者，言家道之本也。</li></ul><p>杨氏时曰 ：家人者，治家人之道也。齐家自夫妇始。舜观刑于二女，文王刑于寡妻，至于兄弟。利女贞者，言家道之本也。</p><ul><li>林氏希元曰 ：所正虽在女，所以正之者则在夫，盖主家之人也。</li></ul><p>林氏希元曰 ：所正虽在女，所以正之者则在夫，盖主家之人也。</p><p>象曰：风自火出，家人；君子以言有物而行有恒</p><h3 id="本义-1" tabindex="-1">本义 <a class="header-anchor" href="#本义-1" aria-label="Permalink to “本义”">​</a></h3><p>身脩则家治矣</p><h3 id="程传-2" tabindex="-1">程传 <a class="header-anchor" href="#程传-2" aria-label="Permalink to “程传”">​</a></h3><p>正家之本在正其身。正身之道，一言一动不可易也。君子观风自火出之象，知事之由内而出，故所言必有物，所行必有恒也。物谓事实，恒谓常度法则也。德业之著于外，由言行之谨于内也。言愼行脩，则身正而家治矣。</p><h3 id="集说-1" tabindex="-1">集说 <a class="header-anchor" href="#集说-1" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>孔氏颖达曰：物，事也。言必有事，即口无择言；行必有常，即身无择行。正家之义，脩于近小。言之与行，君子枢机。出身加人，发迩化远，故举言行以为之诫。</p></li><li><p>杨氏时曰：言忠信则有物，行笃敬则有常。</p></li><li><p>胡氏炳文曰：风自火出，一家之化自吾言行出，皆由内及外，自然薰蒸而成者也。</p></li><li><p>俞氏琰曰：齐家之道，自脩身始。此风自火出，所以为家人之象也。君子知风之自是，齐家以脩身为本，而脩身以言行为先。言必有物而无妄，行必有恒而不改。物谓事实，言而诚实则有物，不诚实则无物也；恒谓常度，行而常久则有恒，不常久则无恒也。</p></li></ul><p>彖曰：家人，女正位乎内，男正位乎外，男女正，天地之大义也</p><h3 id="本义-2" tabindex="-1">本义 <a class="header-anchor" href="#本义-2" aria-label="Permalink to “本义”">​</a></h3><p>以卦体九五六二释“利女贞”之义。</p><h3 id="程传-3" tabindex="-1">程传 <a class="header-anchor" href="#程传-3" aria-label="Permalink to “程传”">​</a></h3><p>彖以卦才而言，阳居五在外也，阴居二处内也。男女各得其正位也，尊卑内外之道正合天地阴阳之大义也。</p><h3 id="集说-2" tabindex="-1">集说 <a class="header-anchor" href="#集说-2" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>孔氏颖逹曰 ：此因二五得正以释家人之义，并明“女贞”之㫖。</p></li><li><p>吴氏曰慎曰 ：先言“女正位乎内”，释“利女贞”也。</p></li></ul><p>家人有严君焉，父母之谓也</p><h3 id="本义-3" tabindex="-1">本义 <a class="header-anchor" href="#本义-3" aria-label="Permalink to “本义”">​</a></h3><p>亦谓二五。</p><h3 id="程传-4" tabindex="-1">程传 <a class="header-anchor" href="#程传-4" aria-label="Permalink to “程传”">​</a></h3><p>家人之道必有所尊严而君长者，谓父母也。虽一家之小，无尊严则孝敬衰，无君长则法度废。有严君而后家道正，家者国之则也。</p><h3 id="集说-3" tabindex="-1">集说 <a class="header-anchor" href="#集说-3" aria-label="Permalink to “集说”">​</a></h3><ul><li>王氏申子曰 ：父道固主乎严，母道尤不可以不严。犹国有尊严之君长也，无尊严则孝敬衰，无君长则法度废。故家人一卦大要以刚严为尚。</li></ul><p>父父子子，兄兄弟弟，夫夫妇妇，而家道正；正家而天下定矣</p><h3 id="本义-4" tabindex="-1">本义 <a class="header-anchor" href="#本义-4" aria-label="Permalink to “本义”">​</a></h3><p>上父初子，五三夫，四二妇，五兄三弟（以卦画推之，又有此象）。</p><h3 id="程传-5" tabindex="-1">程传 <a class="header-anchor" href="#程传-5" aria-label="Permalink to “程传”">​</a></h3><p>父子、兄弟、夫妇各得其道，则家道正矣。推一家之道可以及天下，故家正则天下定矣。</p><h3 id="集说-4" tabindex="-1">集说 <a class="header-anchor" href="#集说-4" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>俞氏琰曰 ：彖辞举其端，故但言“利女贞”。彖传极其全，故兼言男女之正，而又以父子、兄弟、夫妇推广而备言之。</p></li><li><p>林氏希元曰 ：“正家而天下定”犹云“人人亲其亲，长其长而天下平”，不作“正家”之效说。</p></li></ul><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>六十四卦六爻刚柔皆得位者，惟既济而已。此外则中四爻得位者三卦，家人、蹇、渐也。然家人名义独取于风火之卦者，一则风自火出，为风化有原之象；二则蹇、渐之中爻虽得位而初上不皆阳爻。凡易取类，上爻有父之象，故蛊卦下五爻皆曰“父母”，至上爻则变其文也。初爻有子之象，故蛊曰“有子”，观曰“童观”，随、渐曰“小子”，中孚曰“其子”，皆指初爻也。二为女正位乎内，母道也；五为男正位乎外，父道也。然必初上皆阳，然后父子之象备；又必三阳四阴各得其位，然后兄弟、夫妇粲然于一卦之中矣。彖传先举二五，始明其为男女之正，继明其为父母之严，以两爻为卦主也。然后悉推家人以切卦位，既以尽正家之义，又以见家人之象。推配于爻画者，独此卦为合也。本义精且当矣。</p><p>初九：闲有家，悔亡</p><h3 id="本义-5" tabindex="-1">本义 <a class="header-anchor" href="#本义-5" aria-label="Permalink to “本义”">​</a></h3><p>初九以刚阳处有家之始，能防闲之，其悔亡矣。戒占者当如是也。</p><h3 id="程传-6" tabindex="-1">程传 <a class="header-anchor" href="#程传-6" aria-label="Permalink to “程传”">​</a></h3><p>初，家道之始也。闲，谓防闲法度也。治其有家之始，能以法度为之防闲，则不至于悔矣。治家者，治乎众人也。苟不闲之以法度，则人情流放，必至于有悔，失长幼之序，乱男女之别，伤恩义，害伦理，无所不至。能以法度闲之于始，则无是矣。故悔亡也。九，刚明之才，能闲其家者也。不云“无悔”者，群居必有悔，以能闲故亡耳。</p><h3 id="集说-5" tabindex="-1">集说 <a class="header-anchor" href="#集说-5" aria-label="Permalink to “集说”">​</a></h3><ul><li>王氏弼曰 ：凡教在初而法在始，家渎而后严之，志变而后治之，则悔矣。处家人之初，为家人之始，故必闲有家，然后悔亡也。</li></ul><p>王氏弼曰 ：凡教在初而法在始，家渎而后严之，志变而后治之，则悔矣。处家人之初，为家人之始，故必闲有家，然后悔亡也。</p><ul><li>胡氏炳文曰 ：初之时当闲，九之刚能闲。</li></ul><p>胡氏炳文曰 ：初之时当闲，九之刚能闲。</p><ul><li>颜之推曰 ：教子婴孩，教妇初来。</li></ul><p>颜之推曰 ：教子婴孩，教妇初来。</p><p>象曰：闲有家，志未变也</p><h3 id="本义-6" tabindex="-1">本义 <a class="header-anchor" href="#本义-6" aria-label="Permalink to “本义”">​</a></h3><p>志未变而豫防之</p><h3 id="程传-7" tabindex="-1">程传 <a class="header-anchor" href="#程传-7" aria-label="Permalink to “程传”">​</a></h3><p>闲之于始，家人志意未变动之前也。正志未流散变动而闲之，则不伤恩，不失义，处家之善也。是以悔亡。志变而后治，则所伤多矣，乃有悔也。</p><h3 id="集说-6" tabindex="-1">集说 <a class="header-anchor" href="#集说-6" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>苏氏轼曰：忘闲焉，则志变矣。及其未变而闲之，故悔亡。</p></li><li><p>杨氏简曰：治家之道，当防闲其初。及其心志未变而闲之以礼，邪僻之意无由而兴矣。</p></li></ul><p>六二：无攸遂，在中馈，贞吉</p><h3 id="本义-7" tabindex="-1">本义 <a class="header-anchor" href="#本义-7" aria-label="Permalink to “本义”">​</a></h3><p>六二柔顺中正，女之正位乎内者也，故其象占如此。</p><h3 id="程传-8" tabindex="-1">程传 <a class="header-anchor" href="#程传-8" aria-label="Permalink to “程传”">​</a></h3><p>人之处家在骨肉父子之闲，大率以情胜礼，以恩夺义。惟刚立之人，则能不以私爱失其正理。故家人卦大要以刚为善，初、三、上是也。六二以阴柔之才而居柔，不能治于家者也，故无攸遂，无所为而可也。夫以英雄之才，尚有溺情爱而不能自守者，况柔弱之人，其能胜妻子之情乎？如二之才，若为妇人之道，则其正也。以柔顺处中正，妇人之道也。故在中馈，则得其正而吉也。妇人居中而主馈者也，故云“中馈”。</p><h3 id="集说-7" tabindex="-1">集说 <a class="header-anchor" href="#集说-7" aria-label="Permalink to “集说”">​</a></h3><ul><li>孔氏颖逹曰 ：六二履中居位，以阴应阳，尽妇人之义也。妇人之道，巽顺为常，无所必遂。其所职主在于家，中馈食供祭而已。得妇人之正，故曰“无攸遂，在中馈，贞吉”。</li></ul><p>孔氏颖逹曰 ：六二履中居位，以阴应阳，尽妇人之义也。妇人之道，巽顺为常，无所必遂。其所职主在于家，中馈食供祭而已。得妇人之正，故曰“无攸遂，在中馈，贞吉”。</p><ul><li>王氏宗传曰 ：“无攸遂”示不敢有所专也。妇人之职，不过奉祭祀、馈饮食而已，此外无他事也。《诗》曰：“无非无仪，惟酒食是议。”采蘩以供祭祀为不失职，采𬞟以供祭祀为能循法度。推而上之，推而下之，其职守莫不皆然，是之谓贞而吉也。</li></ul><p>王氏宗传曰 ：“无攸遂”示不敢有所专也。妇人之职，不过奉祭祀、馈饮食而已，此外无他事也。《诗》曰：“无非无仪，惟酒食是议。”采蘩以供祭祀为不失职，采𬞟以供祭祀为能循法度。推而上之，推而下之，其职守莫不皆然，是之谓贞而吉也。</p><ul><li>易氏祓曰 ：六二柔顺得位，与九五相应，女正位乎内者也。此爻正所以发明“利女贞”之义。</li></ul><p>易氏祓曰 ：六二柔顺得位，与九五相应，女正位乎内者也。此爻正所以发明“利女贞”之义。</p><p>象曰：六二之吉，顺以巽也</p><h3 id="程传-9" tabindex="-1">程传 <a class="header-anchor" href="#程传-9" aria-label="Permalink to “程传”">​</a></h3><p>二以阴柔居中正，能顺从而卑巽者也，故为妇人之贞吉也。</p><h3 id="案-1" tabindex="-1">案 <a class="header-anchor" href="#案-1" aria-label="Permalink to “案”">​</a></h3><p>六二六四之为顺同。顺者，女之贞也。四位高，故曰顺；在位二，位卑，故曰顺以巽。</p><p>九三：家人嗃嗃，悔厉吉；妇子嘻嘻，终吝</p><h3 id="本义-8" tabindex="-1">本义 <a class="header-anchor" href="#本义-8" aria-label="Permalink to “本义”">​</a></h3><p>以刚居刚而不中，过乎刚者也，故有嗃嗃严厉之象。如是则虽有悔厉而吉也。嘻嘻者，嗃嗃之反，吝之道也。占者各以其德为应，故两言之。</p><h3 id="程传-10" tabindex="-1">程传 <a class="header-anchor" href="#程传-10" aria-label="Permalink to “程传”">​</a></h3><p>嗃嗃，未详字义，然以文义及音意观之，与嗷嗷相类，又若急束之意。九三在内卦之上，主治乎内者也。以阳居刚而不中，虽得正而过乎刚者也。治内过刚，则伤于严急，故家人嗃嗃然。治家过严，不能无伤，故必悔于严厉。骨肉恩胜严过，故悔也。虽悔于严厉，未得寛猛之中，然而家道齐肃，人心祗畏，犹为家之吉也。若妇子嘻嘻，则终至羞吝矣。在卦非有嘻嘻之象，盖对嗃嗃而言，谓与其失于放肆，宁过于严也。嘻嘻，笑乐无节也。自恣无节，则终至败家，可羞吝也。盖严谨之过，虽于人情不能无伤，然苟法度立，伦理正，乃恩义之所存也。若嘻嘻无度，乃法度之所由废，伦理之所由乱，安能保其家乎？嘻嘻之甚，则致败家之凶，但云“吝”者，吝之甚则至于凶，故未遽言凶也。</p><h3 id="集说-8" tabindex="-1">集说 <a class="header-anchor" href="#集说-8" aria-label="Permalink to “集说”">​</a></h3><ul><li>朱子语类 问：易传云正家之道，在于正伦理、笃恩义。今欲正伦理，则有伤恩义；欲笃恩义，又有乖于伦理，如何？ 曰：须是于正伦理处笃恩义，笃恩义而不失伦理，方可。</li></ul><p>朱子语类</p><ul><li><p>问：易传云正家之道，在于正伦理、笃恩义。今欲正伦理，则有伤恩义；欲笃恩义，又有乖于伦理，如何？ 曰：须是于正伦理处笃恩义，笃恩义而不失伦理，方可。</p></li><li><p>胡氏炳文曰 ：嗃嗃以义胜情，虽悔厉而吉；嘻嘻以情胜义，终吝。悔自凶而吉，吝自吉而凶。九三以刚居刚，若能严于家人者，比乎二柔；又若易昵于妇子者，三其在吉凶之闲乎？故悔吝之占两言之。</p></li></ul><p>胡氏炳文曰 ：嗃嗃以义胜情，虽悔厉而吉；嘻嘻以情胜义，终吝。悔自凶而吉，吝自吉而凶。九三以刚居刚，若能严于家人者，比乎二柔；又若易昵于妇子者，三其在吉凶之闲乎？故悔吝之占两言之。</p><p>象曰：家人嗃嗃，未失也；妇子嘻嘻，失家节也</p><h3 id="程传-11" tabindex="-1">程传 <a class="header-anchor" href="#程传-11" aria-label="Permalink to “程传”">​</a></h3><p>虽嗃嗃于治家之道，未为甚失。若妇子嘻嘻，是无礼法，失家之节，家必乱矣。</p><h3 id="集说-9" tabindex="-1">集说 <a class="header-anchor" href="#集说-9" aria-label="Permalink to “集说”">​</a></h3><ul><li>王氏弼曰：以阳处阳，刚严者也。处下体之极，为一家之长者也。行与其慢，宁过乎恭；家与其渎，宁过乎严。是以家人虽嗃嗃悔厉，犹得其道；妇子嘻嘻，乃失其节也。</li></ul><p>六四：富家，大吉</p><h3 id="本义-9" tabindex="-1">本义 <a class="header-anchor" href="#本义-9" aria-label="Permalink to “本义”">​</a></h3><p>阳主义，阴主利。以阴居阴而在上位，能富其家者也。</p><h3 id="程传-12" tabindex="-1">程传 <a class="header-anchor" href="#程传-12" aria-label="Permalink to “程传”">​</a></h3><p>六以巽顺之体而居四，得其正位。位居得其正，为安处之义。巽顺于事而由正道，能保有其富者也。居家之道，能保有其富，则为大吉也。四髙位而独云“富”者，于家而言，髙位家之尊也。能有其富，是能保其家也，吉孰大焉。</p><h3 id="案-2" tabindex="-1">案 <a class="header-anchor" href="#案-2" aria-label="Permalink to “案”">​</a></h3><p>四在他卦，臣道也；在《家人》卦，则亦妻道也。夫主教一家者也，妇主养一家者也。老子所谓“教父食母”是也。自二之“在中馈”进而至于四之“富家”，则内职举矣。</p><p>象曰：富家大吉，顺在位也</p><h3 id="程传-13" tabindex="-1">程传 <a class="header-anchor" href="#程传-13" aria-label="Permalink to “程传”">​</a></h3><p>以巽顺而居正位，正而巽顺，能保有其富者也。富家之大吉也。</p><h3 id="集说-10" tabindex="-1">集说 <a class="header-anchor" href="#集说-10" aria-label="Permalink to “集说”">​</a></h3><ul><li>俞氏琰曰：《礼运》云：“父子笃，兄弟睦，夫妇和，家之肥也。”岂以多财为吉哉？以顺居之，则满而不溢，可以保其家而长守其富，吉孰大焉？</li></ul><p>九五：王假有家，勿恤吉</p><h3 id="本义-10" tabindex="-1">本义 <a class="header-anchor" href="#本义-10" aria-label="Permalink to “本义”">​</a></h3><p>假，至也。如“假于大庙”之假。有家，犹言有国也。九五刚健中正，下应六二之柔顺中正，王者以是至于其家，则勿用忧恤而吉可必矣。盖聘纳后妃之吉占，而凡有是德者遇之皆吉也。</p><h3 id="程传-14" tabindex="-1">程传 <a class="header-anchor" href="#程传-14" aria-label="Permalink to “程传”">​</a></h3><p>九五男而在外，刚而处阳，居尊而中正，又其应顺正于内，治家之至正至善者也。王假有家，五君位，故以王言。假至也，极乎有家之道也。夫王者之道，修身以齐家，家正而天下治矣。自古圣王未有不以恭巳正家为本，故有家之道既至，则不忧劳而天下治矣。勿恤而吉也。五恭巳于外，二正家于内，内外同德，可谓至矣。</p><h3 id="集说-11" tabindex="-1">集说 <a class="header-anchor" href="#集说-11" aria-label="Permalink to “集说”">​</a></h3><ul><li>杨氏文焕曰 ：闲有家，闲之于其始；假有家，则假之于其终也。</li></ul><p>杨氏文焕曰 ：闲有家，闲之于其始；假有家，则假之于其终也。</p><ul><li>丘氏富国曰 ：三五阳刚皆主治家者也。三则而不中，失之遇严，未免有悔厉之失；五刚而得中，威而能爱，尽乎治家之道者，故人无不化，可以勿忧恤而吉也。或曰：治家之道尚严，在彖以严正为吉，五以相爱为义，何也？曰：严以分言正家之义也，爱以情言假家之弟也。假有感格之义，故以相爱言之。</li></ul><p>丘氏富国曰 ：三五阳刚皆主治家者也。三则而不中，失之遇严，未免有悔厉之失；五刚而得中，威而能爱，尽乎治家之道者，故人无不化，可以勿忧恤而吉也。或曰：治家之道尚严，在彖以严正为吉，五以相爱为义，何也？曰：严以分言正家之义也，爱以情言假家之弟也。假有感格之义，故以相爱言之。</p><ul><li>龚氏焕曰 ：假与格同，犹“奏假无言，昭假烈祖”之假，谓感格也。九五以阳刚中正居尊位，为有家之主，盛德至善，所以感格乎家人之心者至矣。王者家大人众，其心难一，有未假者，勿用忧恤而自吉也。盖初之“闲有家”是以法度防闲之，至“王假有家”则躬行有以感化之矣。</li></ul><p>龚氏焕曰 ：假与格同，犹“奏假无言，昭假烈祖”之假，谓感格也。九五以阳刚中正居尊位，为有家之主，盛德至善，所以感格乎家人之心者至矣。王者家大人众，其心难一，有未假者，勿用忧恤而自吉也。盖初之“闲有家”是以法度防闲之，至“王假有家”则躬行有以感化之矣。</p><ul><li>何氏楷曰 ：舜格于文祖，公假于太庙，格、假互用可证。身范既端，故能感格其家，使父父子子、兄兄弟弟、夫夫妇妇各得其所以相敦睦，正家而天下定，故不待忧恤而吉也。</li></ul><p>何氏楷曰 ：舜格于文祖，公假于太庙，格、假互用可证。身范既端，故能感格其家，使父父子子、兄兄弟弟、夫夫妇妇各得其所以相敦睦，正家而天下定，故不待忧恤而吉也。</p><ul><li>游氏曰 ：九五尊位，故以王言。假者，感格之义，王假有庙，其义同也。</li></ul><p>游氏曰 ：九五尊位，故以王言。假者，感格之义，王假有庙，其义同也。</p><h3 id="案-3" tabindex="-1">案 <a class="header-anchor" href="#案-3" aria-label="Permalink to “案”">​</a></h3><p>假字训感格，诸说皆有明证可从。何氏之说于象传之义尤为浃洽也。</p><p>象曰：王假有家，交相爱也</p><h3 id="本义-11" tabindex="-1">本义 <a class="header-anchor" href="#本义-11" aria-label="Permalink to “本义”">​</a></h3><p>程子曰：夫爱其内助，妇爱其刑家</p><h3 id="程传-15" tabindex="-1">程传 <a class="header-anchor" href="#程传-15" aria-label="Permalink to “程传”">​</a></h3><p>王假有家之道者，非止能使之顺从而已，必致其心化诚合。夫爱其内助，妇爱其刑家，交相爱也。能如是者，文王之妃乎？若身脩法立而家未化，未得为假有家之道也。</p><h3 id="集说-12" tabindex="-1">集说 <a class="header-anchor" href="#集说-12" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>郭氏雍曰：父父子子，兄兄弟弟，夫夫妇妇，同大顺而无逆焉者，交相爱之义也。</p></li><li><p>龚氏焕曰：交相爱，则一家之父子、兄弟、夫妇、长幼莫不相爱，非特夫妇而已也。</p></li></ul><p>上九：有孚威如，终吉</p><h3 id="本义-12" tabindex="-1">本义 <a class="header-anchor" href="#本义-12" aria-label="Permalink to “本义”">​</a></h3><p>上九以刚居上，在卦之终，故言正家乆远之道。占者必有诚信严威，则终吉也。</p><h3 id="程传-16" tabindex="-1">程传 <a class="header-anchor" href="#程传-16" aria-label="Permalink to “程传”">​</a></h3><p>上卦之终，家道之成也。故极言治家之本。治家之道，非至诚不能也，故必中有孚信。则能常乆而众人自化为善，不由至诚已且不能常守也，况欲使人乎？故治家以有孚为本。治家者在妻孥情爱之闲，慈过则无严，恩胜则掩义，故家之患常在礼法不足而渎慢生也。长失尊严，少忘恭顺，而家不乱者未之有也。故必有威严，则能终吉。保家之终，在有孚威如二者而已，故于卦终言之。</p><h3 id="集说-13" tabindex="-1">集说 <a class="header-anchor" href="#集说-13" aria-label="Permalink to “集说”">​</a></h3><ul><li>王氏弼曰 ：家道可终，惟信与威。</li></ul><p>王氏弼曰 ：家道可终，惟信与威。</p><ul><li>苏氏轼曰 ：凡言终者，其始未必然也。妇子嘻嘻，其始可乐；威如之吉，其始苦之。</li></ul><p>苏氏轼曰 ：凡言终者，其始未必然也。妇子嘻嘻，其始可乐；威如之吉，其始苦之。</p><ul><li>王氏申子曰 ：家人之终，家道成也。故极言齐家乆逺之道。齐家之道，以诚为本，以严为用。不诚则上下相欺，众事不立；不严则礼法不存，渎慢易生。如此而家道齐者，未之有也。故家人之终，以孚威二者言之。是二者保家道之终吉者也。</li></ul><p>王氏申子曰 ：家人之终，家道成也。故极言齐家乆逺之道。齐家之道，以诚为本，以严为用。不诚则上下相欺，众事不立；不严则礼法不存，渎慢易生。如此而家道齐者，未之有也。故家人之终，以孚威二者言之。是二者保家道之终吉者也。</p><ul><li>何氏楷曰 ：治家观于身，下五爻未及正身之义，故于此爻足其意。盖探本之论，与大象言“有物行有恒”相表里。</li></ul><p>何氏楷曰 ：治家观于身，下五爻未及正身之义，故于此爻足其意。盖探本之论，与大象言“有物行有恒”相表里。</p><p>象曰：威如之吉，反身之谓也</p><h3 id="本义-13" tabindex="-1">本义 <a class="header-anchor" href="#本义-13" aria-label="Permalink to “本义”">​</a></h3><p>谓非作威也，反身自治则人畏服之矣</p><h3 id="程传-17" tabindex="-1">程传 <a class="header-anchor" href="#程传-17" aria-label="Permalink to “程传”">​</a></h3><p>治家之道，以正身为本。故云反身之谓。爻辞谓治家当有威严，而夫子又复戒云当先严其身也。威严不先行于己，则人怨而不服。故云威如而吉者，能自反于身也。孟子所谓“身不行道，不行于妻子”也。</p><h3 id="集说-14" tabindex="-1">集说 <a class="header-anchor" href="#集说-14" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>朱氏震曰：威非外求，反诸身而已。反身则正，正则诚，诚则不怒而威。后世不知所谓威严者，正其身也。或不正而尚威怒，则父子相夷，愈不服矣，安得吉？</p></li><li><p>郭氏雍曰：象明言“有物而行有恒”，而此又言“反身之谓”者，家人之道所以成始成终者，脩身而已。</p></li><li><p>赵氏汝梅曰：爻于初言闲，三言嗃嗃，上言威。圣人虑后世以为威严有馀而亲睦不足，故特释之以反身，谓威如者非严厉以为威，反求诸己而已。</p></li></ul><p>总论</p><p>吴氏曰 ：家人之道，男以刚严为正，女以柔顺为正。初曰闲，三曰厉，上曰威，男子之道也；二、四象传皆曰顺，妇人之道也。五刚而中，非不严也，严而㤗也。</p>',154)])])}const m=l(h,[["render",p]]);export{b as __pageData,m as default};
